#include <stdio.h>

/* 对比「在下标 n/2 处插入一个元素」的操作代价（按操作次数计，确定性） */
int main(void) {
    const int n = 100;
    int mid = n / 2;

    int array_moves = n - mid;        /* 数组：搬移 mid..n-1 共 n-mid 个元素 */
    int list_hops = mid;              /* 链表：先走 mid 步定位 */
    int list_ptr_writes = 2;          /* 再改 2 个指针（保存后继 + 挂接） */

    printf("n = %d，在下标 %d 处插入：\n", n, mid);
    printf("  数组：搬移 %d 个元素（每个 4 字节，memmove 可 SIMD 加速）\n", array_moves);
    printf("  链表：定位 %d 次指针跳转 + %d 次指针写入\n", list_hops, list_ptr_writes);
    printf("  合计：数组 %d 次数据移动 vs 链表 %d 次操作\n",
           array_moves, list_hops + list_ptr_writes);
    printf("\n结论：不带「已知节点指针」时，链表的 O(1) 优势被 O(n) 定位吃掉\n");
    printf("      且链表每次跳转大概率 cache miss，实际差距比次数更大\n");
    return 0;
}
